/* Official website change monitor. Published GitHub data, no browser scraping. */
const CompetitiveIntelligence=(()=>{
 let data=null,loaded=false,view='pages';const $=id=>document.getElementById(id);
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const date=s=>s?new Date(s).toLocaleDateString('en-US',{month:'short',day:'2-digit',year:'numeric'}):'—';
 const safe=u=>{try{return /^https?:$/.test(new URL(u).protocol)}catch{return false}};
 const link=(u,t)=>safe(u)?'<a href="'+esc(u)+'" target="_blank" rel="noopener">'+esc(t)+' ↗</a>':esc(t);
 const image=u=>/^competitive\/images\/[a-f0-9]+\.jpg$/.test(u||'')?'<a href="'+esc(u)+'" target="_blank" rel="noopener"><img src="'+esc(u)+'" loading="lazy" alt="Official website evidence — open original image"></a>':'<p class="muted">저장된 화면이 없습니다.</p>';
 const popupImages=items=>(items||[]).length?'<h4>Promotional popup evidence</h4>'+items.map(image).join(''):'';
 const badge=s=>'<span class="ci-badge ci-'+esc(s.toLowerCase().replaceAll(' ','-'))+'">'+esc(s)+'</span>';
 function options(id,values){const old=$(id).value;$(id).innerHTML='<option value="">All</option>'+[...new Set(values.filter(Boolean))].sort().map(v=>'<option value="'+esc(v)+'">'+esc(v)+'</option>').join('');if(values.includes(old))$(id).value=old;}
 function filter(rows){const m=$('ciMolecule').value,b=$('ciBrand').value,q=$('ciMonth').value,t=$('ciType').value,s=$('ciSearch').value.toLowerCase();return rows.filter(r=>(!m||r.molecule===m)&&(!b||r.brand===b)&&(!t||r.pageType===t)&&(!q||month(r.detectedAt||r.checkedAt)===q)&&(!s||[r.brand,r.operator,r.title,r.url].join(' ').toLowerCase().includes(s)));}
 function month(s){if(!s)return '';const d=new Date(new Date(s).getTime()+9*3600000);return d.toISOString().slice(0,7);}
 function monthLabel(s){return new Date(s+'-01T00:00:00Z').toLocaleDateString('en-US',{month:'short',year:'numeric',timeZone:'UTC'});}
 function pages(){return data.monthlySnapshots?.[$('ciMonth').value]?.pages||data.pages;}
 function summary(r){if(r.types.includes('New monitored page'))return '새 모니터링 페이지 등록 · 첫 기준 화면 저장';return '본문 추가 '+r.addedCount+'개 / 삭제 '+r.removedCount+'개 · 링크 추가 '+r.linksAdded.length+'개 / 삭제 '+r.linksRemoved.length+'개 · PDF 변경 '+r.filesChanged.length+'개 · 이미지 URL 변경 '+(r.imagesChanged||0)+'개'+(r.types.includes('Visual review')?' · 화면 변화 확인 필요':'');}
 function stats(){const rows=filter(pages()),cov=data.coverage.filter(p=>(!$('ciMolecule').value||p.molecule===$('ciMolecule').value)&&(!$('ciBrand').value||p.brand===$('ciBrand').value));$('ciStats').innerHTML=[['Tracked products',cov.filter(p=>p.status==='Tracking').length+' / '+cov.length],['Monitored pages',rows.length],['Changes',filter(data.events).length],['Needs review',rows.filter(p=>p.status==='Needs review').length]].map(([a,b])=>'<div class="ci-stat"><span>'+a+'</span><strong>'+b+'</strong></div>').join('');}
 function table(headers,rows){return '<div class="table-scroll"><table class="data-table"><thead><tr>'+headers.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+rows.join('')+'</tbody></table></div>';}
 function render(){if(!data)return;stats();document.querySelectorAll('[data-ci-view]').forEach(b=>{b.classList.toggle('active',b.dataset.ciView===view);b.setAttribute('aria-pressed',String(b.dataset.ciView===view));});
  let rows,html='';
  if(view==='coverage'){
   rows=data.coverage.filter(p=>(!$('ciMolecule').value||p.molecule===$('ciMolecule').value)&&(!$('ciBrand').value||p.brand===$('ciBrand').value)&&(! $('ciSearch').value||p.brand.toLowerCase().includes($('ciSearch').value.toLowerCase())));
   html=table(['Product / Molecule','Status','Captured / Pages','Official sites'],rows.map(r=>'<tr><td><strong>'+esc(r.brand)+'</strong><small>'+esc(r.molecule)+' · '+(r.kind==='reference'?'Originator':'Biosimilar')+'</small></td><td>'+badge(r.status)+'</td><td>'+r.successful+' / '+r.pages+'</td><td>'+data.sites.filter(s=>s.brand===r.brand).slice(0,3).map(s=>link(s.url,s.operator)).join('<br>')+(r.status==='Not mapped'?'<span class="muted">공식 제품 URL 확인 필요</span>':'')+'</td></tr>'));
  }else if(view==='events'){
   rows=filter(data.events).sort((a,b)=>b.detectedAt.localeCompare(a.detectedAt));
   html=rows.length?rows.map(r=>'<article class="ci-event"><div class="ci-event-head"><div><span class="ci-kicker">'+esc(monthLabel(month(r.detectedAt)))+' · '+esc(r.pageType)+'</span><h3>'+esc(r.brand)+' <span>'+esc(r.operator)+'</span></h3>'+link(r.url,'Official page')+'</div><div>'+r.types.map(badge).join(' ')+'<p class="muted">Detected '+date(r.detectedAt)+'</p></div></div><p class="panel-note">비교 기준 '+date(r.previousCheckedAt)+' → '+date(r.detectedAt)+' · 발견일은 사이트 게시일과 다를 수 있습니다.</p><p><strong>변경 요약: </strong>'+esc(summary(r))+'</p><div class="ci-diff"><section><h4>Added <span>+'+r.addedCount+'</span></h4>'+r.added.map(s=>'<p>'+esc(s)+'</p>').join('')+'</section><section><h4>Removed <span>−'+r.removedCount+'</span></h4>'+r.removed.map(s=>'<p>'+esc(s)+'</p>').join('')+'</section></div>'+resourceList('Added links / resources',r.linksAdded)+resourceList('Removed links / resources',r.linksRemoved)+resourceList('Updated PDF files',r.filesChanged)+'<details><summary>이전·현재 화면 비교</summary><div class="ci-shots"><section><h4>Previous</h4>'+image(r.before)+popupImages(r.beforePopups)+'</section><section><h4>Current</h4>'+image(r.after)+popupImages(r.afterPopups)+'</section></div></details></article>').join(''):'<div class="ci-empty"><h3>아직 감지된 변경이 없습니다.</h3><p>첫 수집은 Baseline으로 저장합니다. 다음 수집부터 이전 기준본과 비교한 변경이 여기에 누적됩니다.</p></div>';
  }else{
   rows=filter(pages()).filter(r=>!$('ciStatus').value||r.status===$('ciStatus').value).sort((a,b)=>(a.status==='Changed'?-1:b.status==='Changed'?1:0)||a.brand.localeCompare(b.brand));
   html=rows.length?table(['Product / Site operator','Page','Status','Last checked','Evidence'],rows.map(r=>'<tr><td><strong>'+esc(r.brand)+'</strong><small>'+esc(r.molecule)+' · '+esc(r.operator)+'</small></td><td>'+link(r.url,r.title||r.url)+'<small>'+esc(r.pageType)+(r.depth?' · Subpage':' · Entry page')+'</small></td><td>'+badge(r.status)+(r.error?'<small>'+esc(r.error)+'</small>':'')+'</td><td>'+date(r.checkedAt)+'<small>Last success: '+date(r.lastSuccess)+'</small></td><td><button type="button" class="ci-evidence" data-ci-page="'+esc(r.id)+'">근거 보기</button></td></tr>')):'<div class="ci-empty">선택 조건에 해당하는 페이지가 없습니다. Product coverage에서 공식 URL 등록 상태를 확인하세요.</div>';
  }
  $('ciResults').innerHTML=html;$('ciResultCount').textContent=rows.length+' '+(view==='coverage'?'products':view==='events'?'changes':'pages');$('ciStatusWrap').hidden=view!=='pages';$('ciMonthWrap').hidden=view==='coverage';$('ciTypeWrap').hidden=view==='coverage';
 }
 function resourceList(title,rows){return rows?.length?'<details><summary>'+title+' ('+rows.length+')</summary><ul>'+rows.map(r=>'<li>'+link(r.url,r.label||r.url)+'</li>').join('')+'</ul></details>':'';}
 function evidence(id){const r=pages().find(p=>p.id===id);if(!r)return;$('ciDetailTitle').textContent=r.brand+' · '+r.pageType;$('ciDetailBody').innerHTML='<p>'+link(r.url,'Official page')+' · '+link(r.evidence,'Official source / provenance')+'</p><p>Checked '+date(r.checkedAt)+' · First seen '+date(r.firstSeen)+'</p><p>'+badge(r.status)+' '+esc(r.error||'')+'</p><p class="panel-note">'+(r.scopeLimited?'탐색 한도에 도달했습니다. URL watchlist에서 제품별 한도를 늘리거나 중요한 세부 URL을 직접 등록할 수 있습니다.':'')+' '+(r.captureMode==='full-page'?'Full-page screenshot · '+esc(r.dimensions?.width)+' × '+esc(r.dimensions?.height)+'px. 이미지 클릭 시 원본을 확대해서 볼 수 있습니다. 팝업은 별도 근거로 보관하며 본문과 함께 텍스트를 비교합니다.':'이전 방식으로 수집된 상단 캡처입니다. 다음 성공 수집부터 전체 페이지로 갱신됩니다.')+'</p><div class="ci-shots"><section><h4>Previous</h4>'+image(r.previousScreenshot)+popupImages(r.previousPopupScreenshots)+'</section><section><h4>Current / last successful</h4>'+image(r.currentScreenshot)+popupImages(r.popupScreenshots)+'</section></div>';$('ciDetail').showModal();}
 async function load(){ $('ciFreshness').textContent='게시 데이터를 불러오는 중입니다…';try{const r=await fetch('competitive/index.json',{cache:'no-store'});if(!r.ok)throw Error('아직 수집 게시본이 없거나 불러오지 못했습니다.');const d=await r.json();if(d.schemaVersion!==1)throw Error('지원하지 않는 데이터 형식입니다.');data=d;options('ciMolecule',d.coverage.map(p=>p.molecule));options('ciBrand',d.coverage.map(p=>p.brand));options('ciMonth',[...Object.keys(d.monthlySnapshots||{}),...d.events.map(p=>month(p.detectedAt)),month(d.checkedAt)]);Array.from($('ciMonth').options).forEach(o=>{if(o.value)o.textContent=monthLabel(o.value)});options('ciType',d.pages.map(p=>p.pageType));$('ciFreshness').textContent='Last checked: '+date(d.checkedAt)+' · '+d.schedule;$('ciScope').textContent='Purple Book '+d.coverage.length+'개 브랜드 · 제품당 최대 '+d.maxPagesPerProduct+'페이지 / 깊이 '+d.maxDepth+'단계 · 공식 링크에서 발견한 페이지만 수집 · 수집 실패는 변경 없음으로 처리하지 않습니다.';$('ciSources').innerHTML=d.catalogs.map(s=>'<p>'+link(s.url,s.operator)+' '+badge(s.status)+(s.error?' <small>'+esc(s.error)+'</small>':'')+'</p>').join('');render();}catch(e){$('ciFreshness').textContent=e.message;}}
 function open(){if(loaded)return;loaded=true;$('ciRefresh').onclick=load;document.querySelectorAll('[data-ci-view]').forEach(b=>b.onclick=()=>{view=b.dataset.ciView;render()});['ciBrand','ciMonth','ciType','ciStatus'].forEach(id=>$(id).onchange=render);$('ciMolecule').onchange=()=>{options('ciBrand',data.coverage.filter(p=>!$('ciMolecule').value||p.molecule===$('ciMolecule').value).map(p=>p.brand));render()};$('ciSearch').oninput=render;$('ciReset').onclick=()=>{['ciMolecule','ciBrand','ciMonth','ciType','ciStatus','ciSearch'].forEach(id=>$(id).value='');options('ciBrand',data.coverage.map(p=>p.brand));render()};$('ciResults').onclick=e=>{const b=e.target.closest('[data-ci-page]');if(b)evidence(b.dataset.ciPage)};$('ciClose').onclick=()=>$('ciDetail').close();load();}
 return {open};
})();
